const raw = $input.first().json;
const body = (raw.body && raw.body.description !== undefined) ? raw.body : raw;
const description = body.description || '';
const material    = body.material    || 'sterling-silver';
const pieceType   = body.pieceType   || 'ring';
const rawImages   = body.images        || [];
const mimeTypes   = body.imageMimeTypes || rawImages.map(() => 'image/jpeg');
const refB64      = rawImages[0] || '';
const refMimeType = mimeTypes[0]  || 'image/jpeg';
// All images as data URLs for the agent to reference
const allDataUrls = rawImages.slice(0,3).map((b,i) =>
  `data:${mimeTypes[i]||'image/jpeg'};base64,${b}`
);
return [{ json: {
  description, material, pieceType,
  refB64, refMimeType,
  allDataUrls,
  imageCount: rawImages.length
} }];

