={{ `You are a jewelry customization specialist. A customer wants to modify a jewelry piece.

Piece type: ${$json.pieceType}
Material: ${$json.material}
Modification request: ${$json.description}
Number of reference photos provided: ${$json.imageCount}

Analyze the reference image carefully, then call the render_jewelry tool to generate the 3 renders and price estimate. Pass the exact modification description and all relevant details to the tool.` }}

parameters.jsCode:
// This tool is called by the AI Agent with full jewelry context
// The agent has already analyzed the reference image and provides visualDescription
const input = typeof query === 'string' ? JSON.parse(query) : query;
const { description, material, pieceType, visualDescription } = input;

// Get reference image data from the workflow context
const parseData = $('Parse Input').first().json;
const refB64      = parseData.refB64      || '';
const refMimeType = parseData.refMimeType || 'image/jpeg';

// Get API key from OpenAI credential
const apiKey = $credentials?.openAiApi?.apiKey || '';

if (!apiKey) {
  return JSON.stringify({ error: 'No OpenAI API key found in credentials' });
}

const angles = [
  { view: 'front',   angle: 'front view, straight on, centered' },
  { view: 'side',    angle: 'side profile view' },
  { view: 'angle45', angle: '45-degree angle view' }
];

const renders = {};

for (const { view, angle } of angles) {
  const prompt = `${angle}: ${visualDescription}. Professional jewelry product photography, pure white seamless background, studio lighting, ultra-high detail, photorealistic. Do not show hands or fingers.`;

  let b64 = '';

  if (refB64) {
    // Use image edit endpoint with reference
    const boundary = 'boundary' + Date.now();
    const imgBytes = Buffer.from(refB64, 'base64');
    const ext = refMimeType.split('/')[1] || 'jpeg';

    const parts = [
      `--${boundary}\r\nContent-Disposition: form-data; name="model"\r\n\r\ngpt-image-1`,
      `--${boundary}\r\nContent-Disposition: form-data; name="prompt"\r\n\r\n${prompt}`,
      `--${boundary}\r\nContent-Disposition: form-data; name="n"\r\n\r\n1`,
      `--${boundary}\r\nContent-Disposition: form-data; name="size"\r\n\r\n1024x1024`,
      `--${boundary}\r\nContent-Disposition: form-data; name="quality"\r\n\r\nmedium`,
    ];

    let bodyStr = parts.join('\r\n') + '\r\n';
    const preamble = Buffer.from(bodyStr, 'utf8');
    const imgHeader = Buffer.from(
      `--${boundary}\r\nContent-Disposition: form-data; name="image[]"; filename="ref.${ext}"\r\nContent-Type: ${refMimeType}\r\n\r\n`,
      'utf8'
    );
    const epilogue = Buffer.from(`\r\n--${boundary}--\r\n`, 'utf8');
    const bodyBuf = Buffer.concat([preamble, imgHeader, imgBytes, epilogue]);

    const resp = await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/images/edits',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': `multipart/form-data; boundary=${boundary}`
      },
      body: bodyBuf,
      encoding: null,
      returnFullResponse: false
    });

    const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
    if (data.error) throw new Error(`Edit error (${view}): ${data.error.message}`);
    b64 = data.data?.[0]?.b64_json || '';

  } else {
    // Fallback: pure generation
    const resp = await $helpers.httpRequest({
      method: 'POST',
      url: 'https://api.openai.com/v1/images/generations',
      headers: {
        'Authorization': `Bearer ${apiKey}`,
        'Content-Type': 'application/json'
      },
      body: JSON.stringify({
        model: 'gpt-image-1',
        prompt,
        n: 1,
        size: '1024x1024',
        quality: 'medium'
      })
    });
    const data = typeof resp === 'string' ? JSON.parse(resp) : resp;
    if (data.error) throw new Error(`Gen error (${view}): ${data.error.message}`);
    b64 = data.data?.[0]?.b64_json || '';
  }

  renders[view] = b64;
}

// Price calculation
const basePrices = { ring: 800, necklace: 1200, bracelet: 1000, earring: 600, pendant: 700 };
const mults = { 'sterling-silver': 1.0, 'gold-14k-18k': 1.5, platinum: 2.0, gold: 1.5, silver: 1.0 };
const pt = (pieceType || 'ring').toLowerCase();
const mt = (material  || 'sterling-silver').toLowerCase();
const mid  = (basePrices[pt] ?? 800) * (mults[mt] ?? 1.0);
const low  = Math.round(mid * 0.8 / 50) * 50;
const high = Math.round(mid * 1.2 / 50) * 50;

return JSON.stringify({
  images: { front: renders.front, side: renders.side, perspective: renders.angle45 },
  price: { min: low, max: high, currency: 'USD' },
  description: `Custom ${pt} in ${mt} — estimated fabrication cost based on material and design complexity.`
});

