// Extract the tool result from the agent output
const agentOutput = $input.first().json.output || '';

// The agent returns the tool result as a JSON string somewhere in its output
// Try to find and parse the JSON block
let result;
try {
  // First try: agent output is directly the JSON
  result = JSON.parse(agentOutput);
} catch(e) {
  // Second try: extract JSON from within the agent's text response
  const match = agentOutput.match(/\{[\s\S]*"images"[\s\S]*\}/);
  if (match) {
    result = JSON.parse(match[0]);
  } else {
    throw new Error('Could not extract render result from agent output: ' + agentOutput.slice(0, 200));
  }
}

return [{ json: result }];
